#!/usr/bin/env bash
# cppcheck over the desktop build's compile_commands.json, with a baseline.
#
#   .github/scripts/cppcheck.sh [BUILD_DIR]            # fail on findings not in the baseline
#   .github/scripts/cppcheck.sh --update [BUILD_DIR]   # rewrite the baseline from today's findings
#
# BUILD_DIR (default build-cppcheck) is configured from port/unix if it has no
# compile_commands.json; configuring needs SDL2 and the tamp submodule but no
# donor ROM. The baseline (.github/cppcheck-suppressions.txt) suppresses by
# id and file, not line, so edits don't shift it: a new finding of an id that
# a file already has passes, any other new finding fails. Fix or suppress
# inline (// cppcheck-suppress id) rather than growing the baseline; shrink it
# when a fix removes the last finding of an id in a file.
#
# CI pins the cppcheck version (see .github/workflows/ci.yml); other versions
# report different findings.
set -euo pipefail

update=0
if [[ "${1:-}" == "--update" ]]; then
    update=1
    shift
fi
root="$(cd "$(dirname "$0")/../.." && pwd)"
build="${1:-build-cppcheck}"
baseline="$root/.github/cppcheck-suppressions.txt"

if [[ ! -f "$build/compile_commands.json" ]]; then
    cmake -S "$root/port/unix" -B "$build" -DCMAKE_EXPORT_COMPILE_COMMANDS=ON >/dev/null
fi
build="$(cd "$build" && pwd)"

# shellcheck disable=SC2054 # the commas are inside cppcheck option values
args=(
    --project="$build/compile_commands.json"
    --enable=warning,style,performance,portability
    --inline-suppr
    --suppress=missingIncludeSystem
    -i"$root/src/vendor"
    -i"$build"
    --template='{id}:{file}:{line}: {message}'
    -j "$(getconf _NPROCESSORS_ONLN)"
    --quiet
)

if [[ $update == 1 ]]; then
    out="$(mktemp)"
    cppcheck "${args[@]}" 2>"$out" >/dev/null
    {
        echo "# cppcheck baseline: id:*/path suppressions, one per (finding id, file)."
        echo "# Generated by .github/scripts/cppcheck.sh --update; see that script."
        sed "s|^\([^:]*\):$root/\([^:]*\):.*|\1:*/\2|" "$out" | grep -v '^#' | sort -u
    } >"$baseline"
    echo "$(grep -vc '^#' "$baseline") baseline entries from $(wc -l <"$out" | tr -d " ") findings -> $baseline"
    rm -f "$out"
    exit 0
fi

cppcheck "${args[@]}" --suppressions-list="$baseline" --error-exitcode=1 >/dev/null
echo "cppcheck: no findings outside the baseline"
